export const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const formatTime=seconds=>`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
export function downloadJSON(data,name='practice-history'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function shape(type,color='#245de8',size=64,rotation=0){const paths={circle:'<circle cx="32" cy="32" r="22"/>',square:'<rect x="11" y="11" width="42" height="42" rx="3"/>',triangle:'<path d="M32 7 58 55H6Z"/>',diamond:'<path d="M32 5 59 32 32 59 5 32Z"/>',star:'<path d="m32 4 8 18 20 2-15 14 5 21-18-11-18 11 5-21L4 24l20-2Z"/>',cross:'<path d="M23 6h18v17h17v18H41v17H23V41H6V23h17Z"/>',arrow:'<path d="M8 23h25V9l24 23-24 23V41H8Z"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 64 64" aria-hidden="true"><g fill="${color}" transform="rotate(${rotation} 32 32)">${paths[type]||paths.circle}</g></svg>`;}
export function gameFrame(root,title,hint){root.innerHTML=`<div class="round-heading"><h2>${title}</h2><p>${hint}</p></div><div class="play-area"></div><div class="feedback" role="status" aria-live="polite"></div>`;return root.querySelector('.play-area');}
export function feedback(root,correct,text){const el=root.querySelector('.feedback');el.className=`feedback ${correct?'correct':'incorrect'}`;el.innerHTML=`<strong>${correct?'Correct.':'Keep practicing.'}</strong> ${escapeHTML(text)}`;}
export function button(text,fn,cls=''){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b;}
export function roundFlow(root,context){let round=0,locked=false;return {next(){round++;locked=false;context.setRound(round);return round;},answer(correct,detail,next,metrics={}){if(locked||!context.session.answer(round,correct))return;locked=true;Object.assign(context.metrics,metrics);context.updateScore();root.querySelectorAll('button,input').forEach(b=>b.disabled=true);feedback(root,correct,detail);if(context.mode==='learn'){if(context.session.stats.attempts>=8){const b=button('See results',()=>context.complete(), 'primary');root.querySelector('.feedback').append(document.createElement('br'),b);}else{const b=button('Next round',next,'primary');root.querySelector('.feedback').append(document.createElement('br'),b);}}else context.session.schedule(next,850);},get round(){return round;},get locked(){return locked;}};}
